app.use((err, req, res, next) => {
  if (res.headersSent) return next(err);
  const instance = `/solicitudes/${req.id}`;
  if (err instanceof ErrorDeApi) {              // esperado: el cliente puede corregirlo
    log("info", "error esperado", { request_id: req.id, status: err.status, tipo: err.tipo });
    return res.status(err.status).type("application/problem+json")
      .json({ type: err.tipo, title: err.titulo, status: err.status, detail: err.message, instance, ...err.extra });
  }
  // inesperado: el detalle va al log; al cliente, un mensaje genérico con el código de la solicitud
  log("error", "error inesperado", { request_id: req.id, error: { name: err.name, message: err.message, stack: err.stack } });
  res.status(500).type("application/problem+json").json({
    type: "about:blank", title: "Error interno", status: 500,
    detail: "Algo falló de nuestro lado. Ya quedó registrado; si pedís ayuda, mencioná el código de la solicitud.", instance });
});

const dormir = (ms) => new Promise((r) => setTimeout(r, ms));

async function ingenuo(almacen, clave, creados) {
  if (almacen.has(clave)) return "repetida";
  await dormir(50);                 // acá trabaja la base
  creados.push(clave);
  almacen.set(clave, "lista");
  return "creada";
}

async function seguro(almacen, clave, creados) {
  if (almacen.has(clave)) return "repetida o en curso";
  almacen.set(clave, "procesando"); // se anota ANTES del await
  await dormir(50);
  creados.push(clave);
  almacen.set(clave, "lista");
  return "creada";
}

for (const [nombre, f] of [["ingenuo", ingenuo], ["seguro", seguro]]) {
  const almacen = new Map(), creados = [];
  const resultados = await Promise.all([f(almacen, "K2", creados), f(almacen, "K2", creados)]);
  console.log(nombre.padEnd(8), JSON.stringify(resultados), "pedidos creados:", creados.length);
}

